// First strike
// Dualcast — The second spell you cast each turn costs {2} less to cast.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_2_0_rule(q: &dyn Query, source: ObjectId, player: PlayerId, costed: Costed, targets: &[Target]) -> CostDelta { let asker = &Asker::new(source, q.controller(source)); let Costed::Spell(spell) = costed else { return CostDelta::NONE; }; if player == asker.controller && (true && q.history().this_turn().iter().filter_map(|r| match r.event { Event::Cast(cast) => Some(cast), _ => None }).take_while(|cast| cast.spell != spell).filter(|cast| Some(asker.controller) == Some(cast.player) && true).count() as i64 + 1 == 2i64) { CostDelta::less((2i64) as u8) } else { CostDelta::NONE } }

